INSERT INTO investigation_case (case_id, case_number, title, description, status, opened_at, closed_at, created_by) VALUES
  (1, 'TX-2026-001', 'Suspicious program contacting an outside server', 'A workstation in the engineering department began making repeated outbound connections to an unfamiliar address shortly after a software download. The investigation aims to establish what ran, what it contacted, and whether data left the network.', 'open', '2026-08-03 09:15:00', NULL, 1),
  (2, 'TX-2026-002', 'Employee copying company files before departure', 'A member of the sales team resigned and, in the days before the last working day, accessed a large number of pricing and customer files. The investigation aims to establish whether files were copied to a removable drive or to a personal online account.', 'open', '2026-08-17 10:30:00', NULL, 2),
  (3, 'TX-2026-003', 'Phishing email and stolen password', 'Several staff received an email claiming their password would expire. At least one employee entered credentials on a fake login page, and the account was then used from an unfamiliar address. The investigation aims to establish how many users were reached, which account was compromised, and what the attacker did with it.', 'under_review', '2026-09-07 08:50:00', NULL, 1),
  (4, 'TX-2026-004', 'Ransomware-style file encryption on a file server', 'Over one night the files on a departmental file server were renamed and became unreadable, and a note demanding payment appeared on the server. The investigation aimed to establish how the attacker gained access, what was affected, and whether backups were harmed. The case was closed after the final report was accepted.', 'closed', '2026-05-11 09:00:00', '2026-07-20 16:00:00', 2),
  (5, 'TX-2026-005', 'Altered financial documents before an audit', 'Before an external audit, several approved invoices and a reconciliation workbook were found to differ from the copies held by the supplier. The investigation aims to establish which documents were changed, when, from which account and device, and whether the changes were discussed in internal messages.', 'open', '2026-09-28 09:30:00', NULL, 2);
