INSERT INTO evidence_source (source_id, case_id, label, source_kind, serial_no, description) VALUES
  (1, 1, 'Engineering workstation WS-114', 'computer', 'WS114-A7731', 'Desktop used by one engineer. Isolated from the network on 2026-08-01.'),
  (2, 1, 'Perimeter traffic tap', 'network_capture', NULL, 'Mirror port at the office firewall.'),
  (3, 1, 'Internal DNS resolver', 'server', 'DNS-01', 'Primary resolver for the office network.'),
  (4, 2, 'Employee laptop L-207', 'computer', 'L207-B5512', 'Company laptop assigned to the departing employee.'),
  (5, 2, 'USB drive 16 GB', 'storage_media', 'USB-4471-9A', 'Removable drive found in the employee''s desk drawer.'),
  (6, 2, 'Corporate cloud storage account', 'cloud_account', NULL, 'Company file-sharing account used by the sales team.'),
  (7, 3, 'Mail server archive', 'server', 'MAIL-01', 'Message store and gateway logs for the company mail system.'),
  (8, 3, 'Employee laptop L-310', 'computer', 'L310-C9921', 'Laptop of the employee who reported clicking the link.'),
  (9, 4, 'File server FS-02', 'server', 'FS02-D3318', 'Departmental file server holding shared project folders.'),
  (10, 4, 'Backup appliance BK-01', 'server', 'BK01-E7740', 'Appliance that stores nightly backups of file servers.'),
  (11, 4, 'Switch mirror port capture', 'network_capture', NULL, 'Copy of traffic to and from the file server.'),
  (12, 5, 'Finance file share FIN-SHARE', 'server', 'FINSH-A5502', 'Shared folder holding approved invoices and reconciliation workbooks.'),
  (13, 5, 'Accountant workstation AW-09', 'computer', 'AW09-K1187', 'Desktop computer of the accountant who prepared the reconciliation.'),
  (14, 5, 'Chat workspace export', 'cloud_account', NULL, 'Export of the finance team''s chat channel and direct messages.');
INSERT INTO evidence (evidence_id, evidence_no, case_id, source_id, type_id, title, description, extracted_text, sha256, file_size_bytes, status, registered_by, registered_at, content_version, indexed_version, indexed_at) VALUES
  (1, 'EV-001-01', 1, 1, 1, 'Disk image of WS-114 system drive', 'Full forensic image of the system drive of workstation WS-114, taken after the workstation was isolated from the network.', 'Image acquired through a hardware write blocker. Partitions: EFI 260 MB, NTFS 465 GB. File system timeline begins 2026-07-29.', '7547582348a52e2945b4f5ab7a61baed09ce7c55b98330811fef183665168609', 499558383616, 'active', 3, '2026-08-03 13:37:33', 1, NULL, NULL),
  (2, 'EV-001-02', 1, 1, 2, 'Windows process creation events from WS-114', 'Process creation events exported from the workstation''s security log covering the 24 hours around the first suspicious connection.', '2026-08-01 08:14:07 ProcessCreate Image=C:/Users/Public/Downloads/updater_setup.exe ParentImage=C:/Program Files/Browser/browser.exe User=CORP/e.rossi\n2026-08-01 08:14:19 ProcessCreate Image=C:/Windows/System32/cmd.exe ParentImage=updater_setup.exe CommandLine="cmd.exe /c whoami && ipconfig /all"\n2026-08-01 08:15:02 ProcessCreate Image=C:/Windows/System32/WindowsPowerShell/v1.0/powershell.exe ParentImage=updater_setup.exe CommandLine="powershell -nop -w hidden -enc [encoded text omitted]"', '50993048e91d6858316fad6ea17c63fe903e17fe11bab437b750bcf364c72bba', 1884160, 'active', 3, '2026-08-03 15:23:02', 1, NULL, NULL),
  (3, 'EV-001-03', 1, 2, 5, 'Packet capture of outbound traffic from WS-114', 'Summary of packets captured at the perimeter tap for the address of WS-114, covering 24 hours from the first suspicious connection.', '08:15:44 192.0.2.114:51822 -> 203.0.113.77:443 TLS ClientHello SNI=cdn-update-sync.example.net\n08:16:44 192.0.2.114:51830 -> 203.0.113.77:443 TLS ClientHello SNI=cdn-update-sync.example.net\nSummary: 412 connections in 24 h, interval 60 s +/- 2 s, same destination.', 'c3aae8de343b2436b8c069a91237fb89880d8755f65e9ce7af5dc329e99879d1', 73400320, 'active', 4, '2026-08-04 14:19:09', 1, NULL, NULL),
  (4, 'EV-001-04', 1, 3, 2, 'DNS query log for the update-themed domain', 'Resolver log lines for the domain contacted by WS-114, covering the first and later lookups.', '2026-08-01 08:15:41 client=192.0.2.114 query=cdn-update-sync.example.net type=A answer=203.0.113.77 ttl=60\n2026-08-01 08:15:41 client=192.0.2.114 query=cdn-update-sync.example.net type=AAAA answer=NXDOMAIN\n2026-08-01 08:16:41 client=192.0.2.114 query=cdn-update-sync.example.net type=A answer=203.0.113.77 ttl=60', 'f76a1ee2c76ed1242b2936499c7eb14ac46dcd6276b81f6376636fbfd7229267', 245760, 'active', 4, '2026-08-04 19:42:37', 1, NULL, NULL),
  (5, 'EV-001-05', 1, 1, 4, 'Memory dump of WS-114 in running state', 'Capture of the workstation''s memory taken before it was powered off.', 'Process list at capture time includes updater_setup.exe (PID 5128) with an open TCP connection to 203.0.113.77:443 and powershell.exe (PID 6040) as its child process.', '98cbfd6fe8abda8e388ff15a027e26ad7b7002d9959958cf0e9472994f9ba65c', 17179869184, 'active', 3, '2026-08-03 12:49:57', 1, NULL, NULL),
  (6, 'EV-001-06', 1, 1, 9, 'Registry autostart entries export from WS-114', 'Export of the per-user and machine autostart registry keys from WS-114.', 'HKCU/Software/Microsoft/Windows/CurrentVersion/Run  SyncHelper = C:/Users/Public/Downloads/updater_setup.exe --background', '5162e967335d53746748d2161608026cf4aae26eac6027ed8bb285ef26ba8205', 18432, 'active', 3, '2026-08-03 19:17:19', 1, NULL, NULL),
  (7, 'EV-001-07', 1, 1, 10, 'Browser download history for the workstation user', 'Download records from the user''s web browser profile on WS-114.', '2026-08-01 08:12:55 download http://downloads.example.org/tools/updater_setup.exe size=2.1 MB referrer=http://forum.example.org/thread/4471', 'c810244153f0657dd519d387b5f32c7a3b7d28344b42026d0455f6fe9ccf8458', 98304, 'active', 3, '2026-08-03 14:21:09', 1, NULL, NULL),
  (8, 'EV-001-08', 1, NULL, 6, 'IT help desk ticket from the affected user', 'Ticket text submitted by the user describing the problem as they saw it.', 'User reports the PC felt slow after installing a tool that promised faster updates. A black command window flashed several times. User did not run any other new software.', NULL, 4096, 'active', 4, '2026-08-04 16:43:49', 1, NULL, NULL),
  (9, 'EV-001-09', 1, 2, 8, 'Firewall alert screenshot for beacon-like connections', 'Screenshot of the firewall dashboard showing the alert raised for repeated connections to the outside address.', NULL, '1dccfb0f3cc7e1581df85d1e67ee2366e20f7bcb62d918f5318d900fbb546755', 356352, 'active', 4, '2026-08-04 17:02:24', 1, NULL, NULL),
  (10, 'EV-001-10', 1, 2, 2, 'Firewall log of allowed outbound connections', 'Firewall rows for connections from WS-114 to the outside address, with byte counts.', '2026-08-01 02:10:13 allow src=192.0.2.114 dst=203.0.113.77 dport=443 bytes_out=48211 bytes_in=1204\n2026-08-01 02:11:13 allow src=192.0.2.114 dst=203.0.113.77 dport=443 bytes_out=51877 bytes_in=1198\n2026-08-01 08:20:02 allow src=192.0.2.114 dst=203.0.113.77 dport=443 bytes_out=640 bytes_in=980', 'cfcddfd546e0cc27b8bcc960820cd6addb88a47a7305f80fda6eace78e22ce70', 512000, 'active', 4, '2026-08-04 20:45:57', 1, NULL, NULL),
  (11, 'EV-001-11', 1, 1, 2, 'Authentication log for the affected user account', 'Logon and file-share access events for the user account during the night of 2026-08-01.', '2026-08-01 02:07:41 logon success user=CORP/e.rossi workstation=WS-114 type=network\n2026-08-01 02:08:10 share access user=CORP/e.rossi path=//fs01/design/projects count=214\n2026-08-01 02:09:55 share access user=CORP/e.rossi path=//fs01/design/archive count=96', 'd70b9bc58832670857985cf8c6f46ab01f607f55697d585b95093a386dee004b', 61440, 'active', 8, '2026-08-05 16:05:56', 1, NULL, NULL),
  (12, 'EV-001-12', 1, NULL, 7, 'Chat export between help desk and the user', 'Messages exchanged in the internal chat tool between the help desk agent and the user before the machine was isolated.', '[07:58] user: I installed it from a forum link, it said it speeds up updates.\n[08:03] helpdesk: Please do not run it again. Can you tell me what the program is called?\n[08:05] user: updater_setup, I think. It is still open in the corner.', NULL, 8192, 'active', 3, '2026-08-04 18:28:02', 1, NULL, NULL),
  (13, 'EV-002-01', 2, 4, 1, 'Disk image of laptop L-207', 'Forensic image of the laptop''s internal drive, taken after the laptop was returned to the IT desk.', 'Image acquired through a hardware write blocker. NTFS volume 238 GB. Last user logon 2026-08-14 17:58.', 'a53cfdc524485eb8f4b69800a93d9a545aa0334056d44896a279ba290af69399', 255550554112, 'active', 4, '2026-08-17 16:18:56', 1, NULL, NULL),
  (14, 'EV-002-02', 2, 4, 9, 'USB device history from laptop registry', 'Registry export listing external storage devices that were connected to the laptop, with first and last connection times.', 'USBSTOR/Disk&Ven_Generic&Prod_Flash_Drive/4471-9A  FirstInstall=2026-08-14 18:02:19  LastConnected=2026-08-14 18:44:03  FriendlyName=Generic Flash Drive USB Device', 'b110d55dfda9b1981d77c693b2ae31331c19d5dad00e742569f628005a709981', 20480, 'active', 4, '2026-08-17 15:12:40', 1, NULL, NULL),
  (15, 'EV-002-03', 2, 6, 2, 'File access audit log for the shared sales folder', 'File server audit records for the employee''s account on the shared sales folder during the two days before departure.', '2026-08-14 18:05:11 read user=CORP/m.fischer path=//fs01/sales/Q3_pricing/price_list_v7.xlsx\n2026-08-14 18:05:12 read user=CORP/m.fischer path=//fs01/sales/Q3_pricing/discount_matrix.xlsx\n2026-08-14 18:05:13 read user=CORP/m.fischer path=//fs01/sales/customers/top_accounts_2026.xlsx\nSummary: 4,812 file reads between 18:05 and 18:41.', '4091cf88163bafcce2db4290e7b4f6418936065677d079ec67dc6984fcfa7eb8', 3145728, 'active', 5, '2026-08-17 15:10:53', 1, NULL, NULL),
  (16, 'EV-002-04', 2, 5, 1, 'Forensic image of the USB drive', 'Forensic image of the 16 GB USB drive recovered from the employee''s desk.', 'FAT32 volume. Top-level folders: Q3_pricing, top_accounts, personal_photos. 1,903 files, 6.2 GB used.', '8224d15c85f9c752924a8f68ca9ac76f78b638e81a9f9f884c1d3bddc6e091c8', 16013942784, 'active', 5, '2026-08-18 13:37:03', 1, NULL, NULL),
  (17, 'EV-002-05', 2, 6, 2, 'Cloud storage audit log for the employee account', 'Sharing and download events for the employee''s account in the company cloud storage.', '2026-08-13 16:20:44 share_link_created user=m.fischer item=Q3_pricing audience=anyone_with_link expires=never\n2026-08-14 18:50:12 download user=m.fischer item=Q3_pricing.zip size=214 MB', '3b7a7cdc8cd8250792e7957c0d4d5234bba2c3b2cb3a7b77fe2ed4828989ee2e', 126976, 'active', 5, '2026-08-17 14:49:33', 1, NULL, NULL),
  (18, 'EV-002-06', 2, NULL, 3, 'Resignation email to the line manager', 'Raw message in which the employee gave notice, with full headers.', 'From: m.fischer@corp.example\nTo: line.manager@corp.example\nDate: Tue, 11 Aug 2026 09:12:30 +0000\nSubject: Notice of resignation\nI will leave on 14 August and will complete the handover of my accounts before then.', NULL, 12288, 'active', 4, '2026-08-17 20:39:09', 1, NULL, NULL),
  (19, 'EV-002-07', 2, NULL, 6, 'HR exit checklist for the employee', 'The HR checklist completed during the employee''s last day.', 'Laptop returned: yes. Badge returned: yes. Cloud access removed: 2026-08-14 19:30. Removable media declared: none.', NULL, 20480, 'active', 5, '2026-08-17 14:34:16', 1, NULL, NULL),
  (20, 'EV-002-08', 2, NULL, 7, 'Chat export with a colleague about taking files home', 'Messages between the employee and a colleague in the company chat tool on 2026-08-13.', '[15:41] colleague: Are you handing over the pricing sheets?\n[15:44] m.fischer: I will keep a copy for my own reference, nothing sensitive.\n[15:45] colleague: Ok, just check with the manager first.', NULL, 6144, 'active', 5, '2026-08-18 19:31:57', 1, NULL, NULL),
  (21, 'EV-002-09', 2, 4, 10, 'Browser history showing a personal webmail and file transfer site', 'Web history from the employee''s browser profile on the laptop for the last three days.', '2026-08-14 18:52:30 visit https://mail.personal-example.test/compose\n2026-08-14 18:53:02 visit https://transfer.example.net/upload\n2026-08-14 18:55:48 visit https://transfer.example.net/upload/complete', '0ea62ed49216b011b6de6e02acd2bcfb49679f8cdcaaba6e772d5a2dea55dbe8', 114688, 'active', 4, '2026-08-17 18:45:10', 1, NULL, NULL),
  (22, 'EV-002-10', 2, 5, 8, 'Screenshot of the USB drive folder properties', 'Screenshot of the folder properties dialog for the pricing folder on the USB drive.', NULL, '1d1592743a634b2ec5f29bb55d25a790cdb7c156253624b5f20da4036a7cdad5', 204800, 'active', 5, '2026-08-18 13:52:53', 1, NULL, NULL),
  (23, 'EV-002-11', 2, 4, 2, 'Endpoint data loss prevention alert log', 'Alerts raised by the endpoint protection agent on the laptop on the employee''s last day.', '2026-08-14 18:06:44 alert policy=removable_media_write severity=medium user=m.fischer action=logged\n2026-08-14 18:06:45 alert policy=bulk_file_read severity=high user=m.fischer action=logged', 'b7835765e6c3072755f13f7fb435df4ce981fe3b599b6aca7d9bba47e7948b50', 40960, 'active', 4, '2026-08-17 14:01:17', 1, NULL, NULL),
  (24, 'EV-002-12', 2, 6, 2, 'Truncated duplicate of the file access audit log', 'A second export of the file access audit log that covers only half of the time range of the main export.', 'Summary: 2,106 file reads between 18:05 and 18:23.', 'ddfe997e42c2a6dec1e86a9be746fb15133d6acbcb2d79dffc6378673a05d32a', 1572864, 'withdrawn', 5, '2026-08-18 12:48:03', 1, NULL, NULL),
  (25, 'EV-003-01', 3, 7, 3, 'Original phishing email with full headers', 'The raw message as delivered to the first reporting employee, including all headers and the body with the link.', 'From: "IT Support" <support@corp-helpdesk.example>\nReply-To: helpdesk-verify@mailbox-example.test\nSubject: Password expires today - action required\nReceived: from mx7.mailbox-example.test [203.0.113.45] by mail.corp.example\nBody: Your password expires in 2 hours. Verify here to keep access: http://corp-helpdesk.example/login-verify', 'a7eb9f653ba0f25dda6570e64b314cf87adba96b6d64e648a16f8c139590e058', 18432, 'active', 3, '2026-09-07 19:49:39', 1, NULL, NULL),
  (26, 'EV-003-02', 3, 7, 3, 'Warning email from a colleague about the message', 'A message from a colleague who recognised the email as suspicious and warned others, 40 minutes after delivery.', 'From: a.nolan@corp.example\nSubject: Re: Password expires today - action required\nThis does not look right, our help desk never asks us to verify through a link. I did not click it.', '2279e29799e673f05a997dfe9052c117957cc45fac6bb3afcdd9908e8217d32e', 9216, 'active', 3, '2026-09-07 16:38:42', 1, NULL, NULL),
  (27, 'EV-003-03', 3, 7, 2, 'Mail gateway delivery log for the phishing message', 'Gateway log lines showing who the message was delivered to and when.', '2026-09-04 07:31:02 deliver msgid=<7f31@mx7.mailbox-example.test> rcpt=a.nolan@corp.example result=delivered\n2026-09-04 07:31:02 deliver msgid=<7f31@mx7.mailbox-example.test> rcpt=r.singh@corp.example result=delivered\nSummary: 37 recipients, 37 delivered, 0 quarantined.', '4475823a2860a145b5dd676d840587091bff3c39ae45d9624c14ec316c369c70', 286720, 'active', 6, '2026-09-07 16:03:24', 1, NULL, NULL),
  (28, 'EV-003-04', 3, 8, 10, 'Browser history on L-310 showing the fake login page', 'Web history from the browser on the laptop of the employee who reported clicking the link.', '2026-09-04 08:02:11 visit http://corp-helpdesk.example/login-verify title=Sign in to verify your account\n2026-09-04 08:02:49 visit http://corp-helpdesk.example/login-verify/done title=Thank you', '94714e63fc3ce190650abf0bf1d4d49d094f6a3fceb9562c157f0e90d4710fe3', 90112, 'active', 3, '2026-09-07 20:13:20', 1, NULL, NULL),
  (29, 'EV-003-05', 3, 8, 2, 'Web proxy log of the form submission', 'Proxy records for the employee''s address during the visit to the fake page.', '2026-09-04 08:02:48 192.0.2.88 POST http://corp-helpdesk.example/login-verify/submit 200 bytes_out=412\n2026-09-04 08:02:48 192.0.2.88 GET http://corp-helpdesk.example/login-verify/done 200', '783b359361fcbf9a92b680a775c09ccf04bbdb7b0b7b8c040049555913bfad16', 51200, 'active', 3, '2026-09-07 20:44:27', 1, NULL, NULL),
  (30, 'EV-003-06', 3, 7, 2, 'Authentication log showing a login from an unfamiliar address', 'Sign-in events for the compromised account on the day of the incident.', '2026-09-04 08:41:19 signin user=r.singh result=success ip=203.0.113.52 country=unknown app=webmail mfa=not_required\n2026-09-04 08:41:20 signin user=r.singh result=success ip=198.51.100.9 country=home app=mobile mfa=satisfied', '75707d4106ad4d1ef377cec9abc7aadcce144e8348c94993f5a58c2ed0bd5767', 69632, 'active', 6, '2026-09-08 18:38:04', 1, NULL, NULL),
  (31, 'EV-003-07', 3, 7, 2, 'Mailbox audit log showing a hidden inbox rule', 'Audit records of rule changes in the compromised mailbox.', '2026-09-04 08:44:07 rule_created user=r.singh by=203.0.113.52 name=. conditions=subject_contains(password|security|verify) action=move_to(RSS Subscriptions) mark_read=true', '9e53beb0ccf74f66b8d8579d33f94aec449fbce3e872ee51809596d4f18b8dcf', 32768, 'active', 6, '2026-09-08 14:07:11', 1, NULL, NULL),
  (32, 'EV-003-08', 3, NULL, 8, 'Screenshot of the fake login page', 'Screenshot of the fake page taken in an isolated test browser.', NULL, '511afd107d5dbfd1b21efaf2a28557202d335f694469c8786ce3ea989c3d568f', 489472, 'active', 6, '2026-09-08 20:05:54', 1, NULL, NULL),
  (33, 'EV-003-09', 3, 8, 5, 'Capture of DNS and web traffic to the phishing domain', 'Traffic capture at the office perimeter for the domain used by the fake page, from the employee''s address.', '08:02:09 192.0.2.88 -> 192.0.2.53 DNS query corp-helpdesk.example A\n08:02:09 192.0.2.53 -> 192.0.2.88 DNS response 203.0.113.60\n08:02:10 192.0.2.88 -> 203.0.113.60:80 HTTP GET /login-verify', 'a835534e3f9c7dd1801f5fb17d95b58d4a24bfaa6b95b77742ca5b926493d774', 20971520, 'active', 3, '2026-09-08 15:28:16', 1, NULL, NULL),
  (34, 'EV-003-10', 3, NULL, 6, 'Help desk ticket from the employee who clicked the link', 'Ticket opened by the employee after being told about the phishing email.', 'Employee reports clicking the link in the password email at around 08:00 and typing the password on the page. Password has since been reset by the help desk.', NULL, 5120, 'active', 3, '2026-09-08 17:29:40', 1, NULL, NULL),
  (35, 'EV-003-11', 3, 8, 1, 'Disk image of laptop L-310 browser profile volume', 'Forensic image of the laptop''s user profile volume, taken to look for saved credentials and downloaded files.', 'NTFS volume 476 GB. Browser profile found at Users/r.singh/AppData/Local. No downloaded executables in the last 14 days.', '4faa8b988f13f636f8f791811b398008b1f4a08513294484b5a1f0471cff540b', 511705088000, 'active', 3, '2026-09-09 19:08:36', 1, NULL, NULL),
  (36, 'EV-003-12', 3, NULL, 8, 'Screenshot taken from the wrong user session', 'A screenshot of an inbox that was later found to belong to a different employee than the compromised account.', NULL, '2086579c3f4e779e1f847dd088bfb660d5b11140f904b03bab026cf4afc1ccf7', 301056, 'withdrawn', 6, '2026-09-09 14:40:19', 1, NULL, NULL),
  (37, 'EV-004-01', 4, 9, 1, 'Disk image of the FS-02 data volume', 'Forensic image of the encrypted data volume of the file server, taken after the server was shut down.', 'Volume 4 TB. 183,402 files renamed with the extension .locked between 01:12 and 03:48. Original file names preserved before the extension.', 'cacb309da789bb8a4bf4469f56716a4dba5c385154da58171ebccae41833b064', 4000787030016, 'active', 6, '2026-05-12 21:40:56', 1, NULL, NULL),
  (38, 'EV-004-02', 4, 9, 2, 'File change log showing mass renaming', 'File server change log listing the rename operations during the incident.', '2026-05-09 01:12:03 rename path=//fs02/projects/alpha/plan.docx -> plan.docx.locked user=SYSTEM process=svc_update.exe\n2026-05-09 01:12:03 rename path=//fs02/projects/alpha/budget.xlsx -> budget.xlsx.locked user=SYSTEM process=svc_update.exe\nSummary: 183,402 renames, rate about 17 per second.', 'bd83dbbe2e14901f090287d5badbedb50f4ce86393dc477930d6c872bd5e5b43', 52428800, 'active', 6, '2026-05-11 13:22:52', 1, NULL, NULL),
  (39, 'EV-004-03', 4, 9, 6, 'Ransom note text file found on the server', 'Text file left in every folder of the file server, demanding payment.', 'All your files have been encrypted. To get them back, contact recover-files@mail-example.test within 72 hours and quote ID 7A21-F9. Do not rename the files or use recovery tools.', 'f7cebb22bd81ca9c75eefae6fa1a545967303632f489266329b2461e565d6ce4', 1024, 'active', 6, '2026-05-11 16:32:45', 1, NULL, NULL),
  (40, 'EV-004-04', 4, 9, 8, 'Screenshot of the ransom note on the server console', 'Screenshot of the server console showing the note displayed at login.', NULL, '369b232afcfb1f231c4367a8cad1711df05f3b36fbf0c6694751635ec4648792', 512000, 'active', 6, '2026-05-11 15:40:28', 1, NULL, NULL),
  (41, 'EV-004-05', 4, 9, 4, 'Memory dump of FS-02 taken before shutdown', 'Capture of the server''s memory taken just before it was powered off.', 'Process svc_update.exe (PID 3320) started 01:11:48 by a scheduled task. Parent service: Task Scheduler. Open handles on 214 files under the projects share.', '28007102fd62a616573b7cc567ed7d2950459e5266a47ef4de4fe5bc8069bc94', 34359738368, 'active', 6, '2026-05-11 21:51:18', 1, NULL, NULL),
  (42, 'EV-004-06', 4, 9, 2, 'Event log entries for shadow copy deletion', 'System event log entries around the start of the encryption.', '2026-05-09 01:10:22 ProcessCreate Image=C:/Windows/System32/vssadmin.exe CommandLine="vssadmin delete shadows /all /quiet" User=SYSTEM\n2026-05-09 01:10:25 ProcessCreate Image=C:/Windows/System32/wbadmin.exe CommandLine="wbadmin delete catalog -quiet" User=SYSTEM', '9561732f8207fdae0f33c2f78be0ccee067975af4d876baa4c157b76710e3a1c', 98304, 'active', 6, '2026-05-12 19:30:11', 1, NULL, NULL),
  (43, 'EV-004-07', 4, 11, 5, 'SMB traffic capture during the encryption', 'Copy of the file-sharing traffic between the file server and the office network during the incident.', '01:09:55 192.0.2.201 -> 192.0.2.20:445 SMB2 session setup user=svc_backup status=success\n01:10:01 192.0.2.201 -> 192.0.2.20:445 SMB2 tree connect //fs02/ADMIN$\nSummary: 1 internal source address, 0 connections to outside addresses.', '93dc0b28cbfd6a9bf9e78cdfc6bfc6938c60e86da8a503c7ddb16c946f7a41ce', 2147483648, 'active', 7, '2026-05-13 19:11:41', 1, NULL, NULL),
  (44, 'EV-004-08', 4, 9, 2, 'Remote desktop logon events for FS-02', 'Remote desktop sign-in events on the server in the 48 hours before the encryption.', '2026-05-08 22:41:03 logon type=10 user=svc_backup source=192.0.2.201 result=success\n2026-05-08 22:41:30 logon type=10 user=svc_backup source=192.0.2.201 result=success\n2026-05-07 14:02:17 logon type=10 user=svc_backup source=192.0.2.201 result=failure count=26', '20b8272b3ff6bcb360b927e3cf29345a9deca1ef09652ed5c75fb6cdb5099010', 40960, 'active', 6, '2026-05-12 12:26:54', 1, NULL, NULL),
  (45, 'EV-004-09', 4, 10, 2, 'Backup job log showing deleted jobs', 'Log of the backup appliance showing job changes before the incident.', '2026-05-08 23:58:40 job_deleted name=FS02-nightly user=svc_backup source=192.0.2.201\n2026-05-08 23:58:52 retention_changed name=FS02-weekly keep=0 user=svc_backup', 'cbd4845281478acf28e6a5cf245ee26d8f6c197d89527b996dedfa48d84158f4', 61440, 'active', 6, '2026-05-12 13:28:57', 1, NULL, NULL),
  (46, 'EV-004-10', 4, 9, 9, 'Registry export showing disabled antivirus protection', 'Export of the server''s antivirus configuration keys.', 'HKLM/SOFTWARE/Policies/Microsoft/Windows Defender  DisableAntiSpyware=1\nHKLM/SOFTWARE/Policies/Microsoft/Windows Defender/Real-Time Protection  DisableRealtimeMonitoring=1  LastWrite=2026-05-08 22:49:11', 'af994bab00d756cfd5efa076f3f25f6a7efc50af3f49667dc834376dee61c232', 12288, 'active', 6, '2026-05-12 16:33:48', 1, NULL, NULL),
  (47, 'EV-004-11', 4, NULL, 6, 'Recovery timeline from the infrastructure team', 'Timeline document written by the infrastructure team during the response.', '08:30 Server found unresponsive. 08:42 Network cable removed. 09:15 Memory captured. 09:40 Server powered off. Restore from the offline monthly copy completed on 2026-05-13.', NULL, 30720, 'active', 7, '2026-05-12 19:14:24', 1, NULL, NULL),
  (48, 'EV-004-12', 4, NULL, 1, 'Disk image of the workstation used for the remote sessions', 'Forensic image of the internal workstation from which the remote desktop sessions originated.', 'NTFS volume 953 GB. Scheduled task svc_update_job created 2026-05-08 23:12. Credential dumping tool found in a temporary folder, deleted 2026-05-09 04:02.', 'cee093f40ffba7d49b708aa3458845e84bf4fac3b4e8a4ee4557d76f7696dcd9', 1024209543168, 'active', 7, '2026-05-14 13:27:57', 1, NULL, NULL),
  (49, 'EV-005-01', 5, 12, 6, 'Invoice INV-4471 as stored on the file share', 'The approved copy of the invoice from the supplier folder, as it exists on the file share now.', 'Invoice INV-4471. Supplier: Northgate Components Ltd. Date: 2026-06-12. Amount payable: 48,900.00. Approved by: finance manager. Document properties: last modified 2026-09-19 18:22 by user acc.rao.', 'f3a7062223d5bebc7beff79c4ecf12319ce129a5d6208c89fd647970392b4337', 184320, 'active', 7, '2026-09-28 19:03:56', 1, NULL, NULL),
  (50, 'EV-005-02', 5, NULL, 3, 'Invoice INV-4471 as received from the supplier', 'The original invoice attached to the supplier''s email in June, retrieved from the mail archive.', 'From: accounts@northgate-example.test\nTo: payables@corp.example\nDate: 2026-06-12\nSubject: Invoice INV-4471\nAttachment: INV-4471.pdf  Amount payable: 14,900.00', 'f3f545ce59d5506e740b45a6d7a8141405a074ba7b6c62ca06f6aaf81e84cc60', 211968, 'active', 7, '2026-09-29 17:16:27', 1, NULL, NULL),
  (51, 'EV-005-03', 5, 12, 2, 'File server audit log for the invoice folder', 'Access log entries for the supplier invoices folder between June and September.', '2026-09-19 18:20:41 open path=//finshare/invoices/northgate/INV-4471.pdf user=acc.rao host=AW-09\n2026-09-19 18:22:03 write path=//finshare/invoices/northgate/INV-4471.pdf user=acc.rao host=AW-09\n2026-09-19 18:22:40 write path=//finshare/invoices/northgate/INV-4488.pdf user=acc.rao host=AW-09', 'edc9b6f5b0d5fc66c3079524ec292da0383493f0cf5b0c0ad45a812869989da8', 143360, 'active', 8, '2026-09-29 13:12:41', 1, NULL, NULL),
  (52, 'EV-005-04', 5, 13, 1, 'Disk image of accountant workstation AW-09', 'Forensic image of the workstation used for the writes to the invoices.', 'NTFS volume 476 GB. Recent files list includes INV-4471.pdf and INV-4488.pdf, accessed 2026-09-19 18:20. A PDF editor was launched at 18:19.', 'a7156ae847b8773165ad43613882e6b3694e2889ec9f79b9b182965922836e52', 511705088000, 'active', 7, '2026-09-30 15:17:56', 1, NULL, NULL),
  (53, 'EV-005-05', 5, 13, 9, 'Registry export of recent documents on AW-09', 'Export of the user''s recent document and program usage keys.', 'HKCU/Software/Microsoft/Windows/CurrentVersion/Explorer/RecentDocs  INV-4471.pdf  INV-4488.pdf  INV-4502.pdf\nHKCU/Software/PdfEditorPro/RecentFiles  INV-4471.pdf  LastWrite=2026-09-19 18:23:10', '269ce4df8ff79d742c3194bf778adb821c6dbf52bb6e7fb11bc3016f6d2a63b9', 20480, 'active', 6, '2026-09-30 17:27:13', 1, NULL, NULL),
  (54, 'EV-005-06', 5, 12, 6, 'Reconciliation workbook Q2 as stored on the file share', 'Workbook that matches payments to invoices for the second quarter.', 'Sheet Summary: Total invoices 412,330.00. Total payments 377,430.00. Difference 34,900.00 marked ''timing''. Sheet Detail row 118: INV-4471 48,900.00.', 'b884cf6e958b5fe8d7a8cf51dffbbf0425ab1b058d2f4ca2c5b7922f7a62117d', 98304, 'active', 8, '2026-10-01 17:50:35', 1, NULL, NULL),
  (55, 'EV-005-07', 5, NULL, 6, 'Earlier version of the reconciliation workbook from backup', 'The same workbook as it was on 2026-09-12, restored from the nightly backup.', 'Sheet Summary: Total invoices 378,330.00. Total payments 377,430.00. Difference 900.00 marked ''rounding''. Sheet Detail row 118: INV-4471 14,900.00.', 'ec6e4c7da1d0198dca47decfa2c9e984bdcff50732905a63b243cb3ab3b8dcd7', 97280, 'active', 8, '2026-10-02 15:04:31', 1, NULL, NULL),
  (56, 'EV-005-08', 5, 14, 7, 'Chat export of the finance channel, September', 'Messages in the finance team channel between 2026-09-14 and 2026-09-30.', '2026-09-19 17:48 acc.rao: audit people arrive on the 29th, I need to tidy up the Northgate paperwork tonight\n2026-09-19 17:52 fin.mgr: ok, just keep the originals\n2026-09-19 19:05 acc.rao: all done\n2026-09-22 09:10 fin.mgr: did you keep the originals?\n2026-09-22 09:14 acc.rao: yes they are on my drive', '3a9089c97bde4abff8d7ac9b9bb078617767c6e034bf941338419d901325594c', 262144, 'active', 6, '2026-10-03 15:27:15', 1, NULL, NULL),
  (57, 'EV-005-09', 5, 14, 7, 'Direct messages between the accountant and the finance manager', 'Private messages between the two people, covering 2026-09-18 to 2026-09-24.', '2026-09-18 16:40 fin.mgr: Northgate asked about the old amount again\n2026-09-18 16:44 acc.rao: I will look at it\n2026-09-24 10:02 fin.mgr: we should not touch the invoices before the audit\n2026-09-24 10:05 acc.rao: understood', '0c29b5996f93bb41b5a934888029ebbcd7e659f309447146c8d367c95397cf84', 40960, 'active', 6, '2026-10-03 13:29:19', 1, NULL, NULL),
  (58, 'EV-005-10', 5, NULL, 6, 'Supplier statement of account', 'Statement sent by the supplier listing invoices and amounts as the supplier recorded them.', 'Northgate Components Ltd statement to 2026-09-30. INV-4471 14,900.00. INV-4488 6,250.00. INV-4502 11,000.00. Balance owed by customer: 32,150.00.', 'd9015299389160d104b0189f1a73d4b0f1dd4a63b85499e15fce2eb9580c098f', 75776, 'active', 7, '2026-10-04 19:29:58', 1, NULL, NULL),
  (59, 'EV-005-11', 5, 12, 6, 'Payments register extract for Northgate', 'Extract of the payments made to the supplier during the second and third quarters.', '2026-06-30 pay INV-4471 14,900.00 ref NG-0630\n2026-07-15 pay INV-4488 6,250.00 ref NG-0715\n2026-08-04 pay INV-4502 11,000.00 ref NG-0804', '199e1062d9b1fa1c6a815600ce7f3b9b8c25471829b30cb1a63d597e1a6608a2', 28672, 'active', 8, '2026-10-05 14:51:17', 1, NULL, NULL),
  (60, 'EV-005-12', 5, 12, 6, 'Memo attributed to the finance manager about the changes', 'A memo found in the finance folder that appears to authorise correcting the Northgate invoices. It was later found to come from a different person and department.', 'Memo: Please correct the Northgate invoice amounts to the agreed revised figures before the audit. Signed: finance manager.', '6453c67b15b587f3ee2afd3c447032e5f4083ac49ad300ad78dbcf243cb18a81', 14336, 'withdrawn', 8, '2026-10-05 18:48:10', 1, NULL, NULL);
