INSERT INTO finding (finding_id, analysis_id, title, description, severity, created_at, content_version, indexed_version, indexed_at) VALUES
  (1, 1, 'Unsigned installer found in a public download folder', 'A program named updater_setup.exe was created in the public downloads folder on 2026-08-01 shortly before the unusual network activity began. The file is not digitally signed.', 'medium', '2026-08-05 18:36:37', 1, NULL, NULL),
  (2, 1, 'Executable copied to a second location', 'A copy of the same program exists under a user application data folder, which is consistent with an attempt to keep it after a reboot.', 'medium', '2026-08-05 23:28:57', 1, NULL, NULL),
  (3, 2, 'Downloaded program launched system commands within seconds', 'The downloaded program started a command window that listed the user name and network settings, then started a hidden PowerShell window. Reconnaissance followed by hidden scripting is a common pattern after a malicious download.', 'high', '2026-08-08 10:26:59', 1, NULL, NULL),
  (4, 2, 'Hidden encoded PowerShell command executed', 'The PowerShell command used an encoded argument and a hidden window. The decoded content was not preserved in this export.', 'high', '2026-08-07 20:19:49', 1, NULL, NULL),
  (5, 3, 'Regular connections at one-minute intervals', 'The workstation contacted the same outside address almost exactly every 60 seconds for a full day. Such a fixed interval is typical of automated check-ins to a remote controller, not of human browsing.', 'high', '2026-08-07 04:32:44', 1, NULL, NULL),
  (6, 3, 'Encrypted traffic to an unfamiliar update-themed domain', 'All connections used encrypted web traffic to a domain whose name suggests software updates but which is not used by any approved vendor.', 'medium', '2026-08-06 21:20:20', 1, NULL, NULL),
  (7, 4, 'Very short lifetime on the domain record', 'The domain''s address record expires after 60 seconds, which lets an operator move the destination quickly. Short lifetimes are common for infrastructure that is meant to be hard to block.', 'low', '2026-08-07 10:03:09', 1, NULL, NULL),
  (8, 5, 'Suspicious program still running with a live connection', 'At capture time the downloaded program was still running and held an open connection to the outside address, which ties the program to the network traffic.', 'high', '2026-08-06 11:59:37', 1, NULL, NULL),
  (9, 6, 'Possible injected code region in PowerShell process', 'A memory region with execute permission and no backing file was found in the PowerShell process. This needs confirmation before it is treated as injected code.', 'medium', '2026-08-09 04:38:07', 1, NULL, NULL),
  (10, 7, 'Program registered to start at every logon', 'An autostart entry named SyncHelper launches the downloaded program in the background each time the user logs in, so the program would survive a restart.', 'high', '2026-08-08 04:27:35', 1, NULL, NULL),
  (11, 8, 'Program came from a forum link, not an approved source', 'The installer was downloaded about two minutes before it ran, from an unofficial site reached through a discussion forum thread.', 'medium', '2026-08-06 05:19:21', 1, NULL, NULL),
  (12, 9, 'Screenshot timestamp matches the alert time', 'The image creation time matches the alert time shown on screen, so the screenshot appears to be a faithful capture of the dashboard.', 'info', '2026-08-08 04:38:49', 1, NULL, NULL),
  (13, 10, 'Larger uploads during the night', 'Overnight connections sent about 50 KB each, far more than the roughly 600 bytes sent during the day. This suggests data was being sent out at night, but the content is not visible in these logs.', 'high', '2026-08-09 20:19:51', 1, NULL, NULL),
  (14, 10, 'Outbound data exceeds data received', 'The workstation sent over forty times more data than it received on those connections, which is unusual for a normal software update.', 'medium', '2026-08-09 02:34:13', 1, NULL, NULL),
  (15, 11, 'Many design files read in the middle of the night', 'The account read more than 300 design files from the file server between 02:08 and 02:10, outside normal working hours, shortly before the larger uploads to the outside address.', 'high', '2026-08-09 10:03:47', 1, NULL, NULL),
  (16, 11, 'Activity not explained by the user''s ticket', 'The help desk ticket describes only slowness. It does not mention being at the computer at 02:07, which raises the question of whether the activity was automated.', 'medium', '2026-08-09 15:46:20', 1, NULL, NULL),
  (17, 12, 'Shortcuts to files on a removable drive', 'Recent file shortcuts point to documents on drive letter E:, a drive that is not present on the laptop. This is consistent with files being opened from or saved to a removable drive.', 'medium', '2026-08-21 08:47:53', 1, NULL, NULL),
  (18, 12, 'Compressed archive created in the user''s folder', 'A file named q3_pricing_pack.zip was created on 2026-08-14 at 18:07 and deleted four minutes later. The deleted file was recovered from unallocated space.', 'high', '2026-08-22 00:09:22', 1, NULL, NULL),
  (19, 13, 'Drive serial matches the drive found in the desk', 'The serial 4471-9A in the registry is the same as the serial printed on the drive recovered from the employee''s desk drawer, so that drive was connected to this laptop.', 'high', '2026-08-21 16:21:39', 1, NULL, NULL),
  (20, 14, 'Burst of nearly five thousand file reads in 36 minutes', 'The account read 4,812 files in about 36 minutes after normal working hours. The employee''s normal daily average is a few dozen files.', 'high', '2026-08-19 23:11:14', 1, NULL, NULL),
  (21, 14, 'Activity matches the time the USB drive was connected', 'The read burst starts three minutes after the USB drive was first connected to the laptop and ends before it was disconnected.', 'high', '2026-08-19 23:13:36', 1, NULL, NULL),
  (22, 15, 'Company pricing and customer files on the drive', 'The drive holds pricing spreadsheets and a customer account list that match files in the shared sales folder by name and size.', 'high', '2026-08-20 20:00:33', 1, NULL, NULL),
  (23, 15, 'Files copied on the evening of 2026-08-14', 'File creation times on the drive fall between 18:05 and 18:41 on 2026-08-14, matching the audit log read burst.', 'high', '2026-08-20 19:27:26', 1, NULL, NULL),
  (24, 16, 'Public link created for the pricing folder', 'A link that works for anyone who has it and never expires was created for the pricing folder one day before the file read burst. Whether anyone outside the company opened it is not shown in this log.', 'high', '2026-08-18 18:10:10', 1, NULL, NULL),
  (25, 16, 'Large archive downloaded after hours', 'A 214 MB archive of the pricing folder was downloaded at 18:50, after the USB drive was disconnected.', 'medium', '2026-08-19 03:11:02', 1, NULL, NULL),
  (26, 17, 'Employee declared no removable media', 'The checklist records that no removable media was declared, although a USB drive was connected to the laptop on the employee''s last day.', 'medium', '2026-08-20 01:36:34', 1, NULL, NULL),
  (27, 18, 'Visit to a file upload service after the download', 'The browser visited an upload service about five minutes after the cloud archive was downloaded and reached a completion page. The content of the upload is not recorded in the history.', 'medium', '2026-08-23 16:22:22', 1, NULL, NULL),
  (28, 19, 'Screenshot shows folder size and file count', 'The dialog shows 1,203 files and 4.4 GB in the pricing folder, which matches the count from the forensic image of the drive.', 'info', '2026-08-25 01:03:23', 1, NULL, NULL),
  (29, 20, 'Alerts were logged but not blocked', 'Both alerts were set to log only, so the protection agent recorded the activity without stopping it or notifying anyone.', 'low', '2026-08-24 00:07:00', 1, NULL, NULL),
  (30, 21, 'Sender address imitates the company help desk', 'The display name says IT Support and the domain looks like the company help desk, but the domain is not owned by the company and the reply address points to a different outside domain.', 'high', '2026-09-10 22:16:21', 1, NULL, NULL),
  (31, 21, 'Urgency and a login link', 'The message creates time pressure and asks the reader to log in through a link to an outside domain, which are typical features of credential phishing.', 'medium', '2026-09-11 01:04:01', 1, NULL, NULL),
  (32, 22, 'Message reached 37 mailboxes without being blocked', 'All 37 recipients received the message and the gateway did not quarantine any copy.', 'high', '2026-09-10 06:13:56', 1, NULL, NULL),
  (33, 22, 'All deliveries in a two-minute window', 'The mass delivery occurred within two minutes, which is consistent with a single bulk send.', 'info', '2026-09-10 04:57:49', 1, NULL, NULL),
  (34, 23, 'Employee visited the fake login page and submitted a form', 'The history shows a visit to the page followed 38 seconds later by a thank-you page, which fits the entry and submission of credentials.', 'high', '2026-09-12 00:30:42', 1, NULL, NULL),
  (35, 24, 'Form data sent to the outside domain', 'The proxy recorded a POST of 412 bytes to the fake page, consistent with a username and password being sent.', 'high', '2026-09-12 13:00:25', 1, NULL, NULL),
  (36, 25, 'Account used from an address the user never uses', 'About 40 minutes after the credentials were submitted, the account signed in to webmail from an address not seen before, without a second authentication step.', 'high', '2026-09-11 05:18:43', 1, NULL, NULL),
  (37, 25, 'Second factor not required for webmail', 'Webmail sign-in did not ask for the second factor that the mobile sign-in used, which allowed the stolen password to be enough.', 'medium', '2026-09-11 10:57:35', 1, NULL, NULL),
  (38, 26, 'Rule hides security-related messages', 'A rule with a nearly empty name moves any message mentioning passwords, security or verification into an unused folder and marks it as read. This would hide warnings from the real owner.', 'high', '2026-09-14 08:45:30', 1, NULL, NULL),
  (39, 27, 'Fake page copies company logo and layout', 'The page reproduces the company logo and the colours of the real login page. Small spelling differences in the footer text are visible.', 'medium', '2026-09-13 13:28:09', 1, NULL, NULL),
  (40, 28, 'Page was served over unencrypted web traffic', 'The fake page was reached over plain HTTP, so the submitted form data crossed the network unencrypted as well.', 'low', '2026-09-12 00:19:30', 1, NULL, NULL),
  (41, 29, 'No malicious downloads found so far', 'The review has not found downloaded programs on the laptop, which suggests the compromise was limited to the stolen password. The review is not finished.', 'info', '2026-09-16 14:26:11', 1, NULL, NULL),
  (42, 30, 'Files renamed in a fixed order across all folders', 'The encryption touched project folders alphabetically, starting with the oldest data. This fits a scripted tool, not manual action.', 'medium', '2026-05-18 09:53:14', 1, NULL, NULL),
  (43, 30, 'Original contents unrecoverable from the volume', 'The files contain high-entropy data throughout, and no unencrypted copies were found on the volume.', 'high', '2026-05-19 13:42:19', 1, NULL, NULL),
  (44, 31, 'All renames made by a single unfamiliar process', 'Every rename was performed by a program named svc_update.exe running as the system account, which is not part of the server''s standard software.', 'high', '2026-05-15 07:39:32', 1, NULL, NULL),
  (45, 31, 'Encryption ran for about two and a half hours', 'The renames started at 01:12 and stopped at 03:48 at a steady rate, which indicates the process ran unattended.', 'medium', '2026-05-14 02:48:18', 1, NULL, NULL),
  (46, 32, 'Note names a contact address and a deadline', 'The note demands contact within 72 hours at an anonymous mailbox. No payment amount or wallet is included in the note itself.', 'info', '2026-05-17 04:32:12', 1, NULL, NULL),
  (47, 33, 'Photo time is consistent with the shutdown log', 'The camera timestamp is about ten minutes before the recorded shutdown of the server.', 'info', '2026-05-14 00:41:20', 1, NULL, NULL),
  (48, 34, 'Encrypting process was started by a scheduled task', 'The program was started by the task scheduler one minute before the first rename, so a task must have been created beforehand by someone with administrator access.', 'high', '2026-05-17 01:57:19', 1, NULL, NULL),
  (49, 35, 'Local recovery points deleted before encryption', 'Commands that delete local snapshots and the backup catalogue ran about two minutes before the encryption began, which removes the easiest way to restore files.', 'high', '2026-05-18 23:33:00', 1, NULL, NULL),
  (50, 36, 'Access came from one internal workstation using a service account', 'The administrative session originated from an internal address and used a backup service account, not a person''s own account.', 'high', '2026-05-15 22:10:32', 1, NULL, NULL),
  (51, 36, 'No outside connections seen from the server', 'The server made no connections to outside addresses during the capture, so there was no sign of data being sent out from the server.', 'info', '2026-05-15 21:25:14', 1, NULL, NULL),
  (52, 37, 'Many failed sign-ins followed by a success', 'Twenty-six failed remote desktop sign-ins for the backup service account came from one address the day before the successful sign-in. This pattern fits password guessing.', 'high', '2026-05-17 01:12:12', 1, NULL, NULL),
  (53, 37, 'Remote desktop access used by a service account', 'Service accounts are normally not used for interactive sessions. The sessions at 22:41 were interactive.', 'medium', '2026-05-16 18:18:33', 1, NULL, NULL),
  (54, 38, 'Backup jobs removed an hour before encryption', 'The nightly and weekly backup jobs for the file server were deleted or set to keep nothing about an hour before the encryption, which would have removed all restore points.', 'high', '2026-05-16 13:48:18', 1, NULL, NULL),
  (55, 38, 'Offline backup copy was not affected', 'A monthly offline copy stored away from the appliance was unaffected and was later used to restore data.', 'info', '2026-05-16 15:03:17', 1, NULL, NULL),
  (56, 39, 'Real-time protection switched off the night before', 'Antivirus real-time monitoring was disabled by policy about eight minutes after the first remote desktop sign-in, which explains why the encrypting program ran unhindered.', 'high', '2026-05-16 18:48:37', 1, NULL, NULL),
  (57, 40, 'Credential theft tool recovered from deleted files', 'A tool that extracts stored passwords was recovered from deleted files on the workstation, which fits how the backup service account password could have been obtained.', 'high', '2026-05-18 12:36:14', 1, NULL, NULL),
  (58, 40, 'Workstation was the origin of the remote sessions', 'The scheduled task that started the encrypting program was created from this workstation, which ties the earlier sessions to the encryption.', 'high', '2026-05-18 01:22:26', 1, NULL, NULL),
  (59, 41, 'Invoice was modified three months after its date', 'The file properties show a modification on 2026-09-19, long after the invoice date and approval, although approved invoices should not change.', 'high', '2026-10-05 03:41:18', 1, NULL, NULL),
  (60, 41, 'Amount field differs from the supplier copy', 'The supplier''s copy shows 14,900.00 payable, while the stored copy shows 48,900.00.', 'high', '2026-10-03 21:27:50', 1, NULL, NULL),
  (61, 42, 'Attachment unchanged since receipt', 'The attachment''s creation and modification times match the supplier''s sending time, so this copy was not edited after receipt.', 'medium', '2026-10-03 04:16:59', 1, NULL, NULL),
  (62, 43, 'Three invoices were written to on one evening', 'Writes to three invoices by one user account within about two minutes, all from one workstation, in the evening after normal hours.', 'high', '2026-10-03 19:08:27', 1, NULL, NULL),
  (63, 43, 'The account used is the accountant''s own', 'The writes were made by the accountant''s account from AW-09, which shows whose credentials were used but not who was seated at the keyboard.', 'info', '2026-10-04 00:09:50', 1, NULL, NULL),
  (64, 44, 'PDF editor was used just before the writes', 'A PDF editing program was started a minute before the first file was opened, which fits editing the invoices rather than only viewing them.', 'high', '2026-10-02 19:56:28', 1, NULL, NULL),
  (65, 44, 'Backup copies of originals were made then deleted', 'Copies of the original invoices were saved to a temporary folder and deleted the same evening.', 'medium', '2026-10-02 19:26:30', 1, NULL, NULL),
  (66, 45, 'Third invoice opened in the editor but not yet checked', 'INV-4502 also appears in the editor''s recent list. The file share shows no write for it, so whether it was changed is still unknown.', 'low', '2026-10-02 10:21:06', 1, NULL, NULL),
  (67, 46, 'Unexplained difference labelled as timing', 'A difference of 34,900.00 is marked as a timing difference, but the payments register shows no later payment that would clear it.', 'medium', '2026-10-06 00:38:51', 1, NULL, NULL),
  (68, 46, 'Workbook last saved the same evening as the invoice changes', 'The workbook was last saved at 18:41 on 2026-09-19, about twenty minutes after the last invoice write.', 'medium', '2026-10-05 23:49:31', 1, NULL, NULL),
  (69, 47, 'Earlier workbook agrees with the supplier''s invoice amount', 'In the earlier version row 118 shows 14,900.00 and the difference is only 900.00, which supports the supplier''s amount.', 'high', '2026-10-09 10:31:29', 1, NULL, NULL),
  (70, 47, 'Edits increased invoice total by exactly the extra 34,000.00', 'The summary total rose by 34,000.00 between the versions, equal to the change on INV-4471 alone. The remaining changes on the other invoices explain the rest.', 'medium', '2026-10-09 18:45:36', 1, NULL, NULL),
  (71, 48, 'Messages mention tidying paperwork on the evening of the writes', 'The accountant wrote that the paperwork would be tidied that evening and wrote ''all done'' shortly after the last file event. The wording is ambiguous: it could mean formatting, not changing amounts.', 'info', '2026-10-07 04:32:23', 1, NULL, NULL),
  (72, 49, 'Statement amounts match the supplier''s original invoices', 'All three invoice amounts agree with the copies received in June, which supports that the stored copies were altered.', 'high', '2026-10-07 06:30:44', 1, NULL, NULL),
  (73, 50, 'Money actually paid matches the supplier, not the altered files', 'The amounts paid equal the supplier''s original invoices, so the altered stored amounts never matched real payments.', 'high', '2026-10-06 22:46:21', 1, NULL, NULL);
INSERT INTO evidence_relationship (rel_id, evidence_a_id, evidence_b_id, rel_type, rationale, recorded_by, recorded_at) VALUES
  (1, 7, 2, 'related_activity', 'The download recorded in the browser history is the program that appears as the first process in the creation log.', 3, '2026-08-06 11:20:44'),
  (2, 2, 3, 'related_activity', 'The hidden PowerShell session starts at 08:15:02 and the first outbound connection to the outside address is at 08:15:44.', 4, '2026-08-06 16:05:40'),
  (3, 3, 4, 'corroborates', 'The DNS lookups match the destination and timing of the captured connections.', 3, '2026-08-07 15:29:03'),
  (4, 4, 10, 'corroborates', 'The resolved address 203.0.113.77 is the same destination shown in the firewall log.', 4, '2026-08-07 16:36:35'),
  (5, 3, 10, 'corroborates', 'Packet capture and firewall log both show the same destination and connection volume.', 3, '2026-08-08 13:05:46'),
  (6, 10, 9, 'corroborates', 'The alert screenshot reports the same repeated connections found in the firewall log.', 4, '2026-08-08 17:18:40'),
  (7, 9, 3, 'corroborates', 'The alert described in the screenshot is consistent with the one-minute interval found in the packet capture.', 3, '2026-08-09 17:25:19'),
  (8, 5, 6, 'related_activity', 'The process held in memory is the same program that is registered to start at logon.', 8, '2026-08-09 16:57:04'),
  (9, 14, 16, 'corroborates', 'The serial 4471-9A in the registry history matches the serial of the drive imaged as evidence 4.', 4, '2026-08-19 17:19:50'),
  (10, 15, 16, 'corroborates', 'File read times on the server match the creation times of the files found on the USB drive.', 5, '2026-08-19 15:53:27'),
  (11, 16, 13, 'related_activity', 'The pricing folder on the USB drive matches the archive recovered from unallocated space on the laptop.', 4, '2026-08-20 11:04:04'),
  (12, 18, 17, 'related_activity', 'The resignation notice and the sharing and download activity in the cloud account fall in the same last week.', 5, '2026-08-20 16:50:11'),
  (13, 19, 14, 'contradicts', 'The checklist says no removable media was declared, but the registry shows a drive was connected on the last day.', 4, '2026-08-20 10:59:58'),
  (14, 25, 27, 'related_activity', 'The delivery log lists the same message that is held as the original email.', 3, '2026-09-08 16:47:15'),
  (15, 27, 28, 'related_activity', 'The employee''s address appears among the 37 recipients and the fake page visit follows delivery.', 6, '2026-09-09 11:33:03'),
  (16, 28, 29, 'corroborates', 'The proxy records a form submission at the time the history shows the thank-you page.', 3, '2026-09-09 14:23:18'),
  (17, 29, 30, 'related_activity', 'The sign-in from the unfamiliar address occurs about 40 minutes after the form submission.', 6, '2026-09-10 15:40:36'),
  (18, 30, 31, 'related_activity', 'The hidden rule was created three minutes after the first sign-in from the unfamiliar address.', 3, '2026-09-10 12:07:49'),
  (19, 43, 44, 'related_activity', 'The remote desktop sessions by the backup account were followed by deletion of backup jobs within the hour.', 6, '2026-05-14 15:37:49'),
  (20, 44, 42, 'related_activity', 'Deleted backup jobs and deleted local snapshots both prepared the system for the encryption.', 6, '2026-05-14 13:36:40'),
  (21, 42, 38, 'related_activity', 'The shadow copy deletion commands ran about two minutes before the first rename in the change log.', 5, '2026-05-15 14:27:48'),
  (22, 38, 37, 'corroborates', 'The change log and the disk image show the same number of renamed files and the same extension.', 7, '2026-05-16 10:10:14'),
  (23, 48, 43, 'corroborates', 'The workstation image shows the origin of the sessions listed in the remote desktop log.', 6, '2026-05-17 12:52:23'),
  (24, 45, 42, 'related_activity', 'Disabled antivirus protection was changed shortly before the shadow copy commands ran.', 7, '2026-05-17 11:42:18'),
  (25, 49, 50, 'contradicts', 'The stored invoice shows 48,900.00 while the supplier''s original shows 14,900.00.', 8, '2026-09-30 17:44:08'),
  (26, 51, 49, 'related_activity', 'The audit log shows the write to the invoice file that matches its modified time.', 7, '2026-09-30 13:54:55'),
  (27, 52, 51, 'corroborates', 'The workstation image shows the editor use at the same time as the writes in the audit log.', 6, '2026-10-02 15:59:08'),
  (28, 53, 52, 'corroborates', 'Registry recent file keys agree with the recent files found on the disk image.', 6, '2026-10-02 17:41:58'),
  (29, 55, 54, 'contradicts', 'The earlier workbook shows 14,900.00 on the line where the current workbook shows 48,900.00.', 8, '2026-10-03 13:23:22'),
  (30, 56, 51, 'related_activity', 'The chat message about tidying paperwork precedes the evening of the writes.', 8, '2026-10-05 12:29:48'),
  (31, 58, 50, 'corroborates', 'The supplier statement agrees with the original invoice amount.', 7, '2026-10-06 12:24:22'),
  (32, 59, 58, 'corroborates', 'The payments made equal the amounts on the supplier statement.', 8, '2026-10-07 13:12:44'),
  (33, 59, 49, 'contradicts', 'The payment made does not match the amount in the stored invoice.', 8, '2026-10-07 12:00:58');
